class Solution {
public:
    int longestRepeatingSubstring(string s) {
        int n = s.size();
        vector<int> dp(n + 1, 0);
        int answer = 0;
        for (int i = 1; i <= n; ++i) {
            for (int j = n; j > i; --j) {
                if (s[i - 1] == s[j - 1]) {
                    dp[j] = dp[j - 1] + 1;
                    answer = max(answer, dp[j]);
                } else {
                    dp[j] = 0;
                }
            }
        }
        return answer;
    }
};
